  {const q=at(0);m.head.position.set(q.p.x/s,q.p.y/s+.06,q.p.z/s);_e.set(o.hp||0,o.hy!=null?o.hy:yaw(q.d,0),0);m.head.quaternion.setFromEuler(_e);}
